boolean valid = false;
while (!valid) {
    String input = scanner.nextLine();
    if (input.equals("1")) {
        // do option 1
        valid = true;
    } else if (input.equals("2")) {
        // do option 2
        valid = true;
    } else if (input.equals("3")) {
        // do option 3
        valid = true;
    } else {
        System.out.println("Invalid choice. Try again.");
    }
}
